type Scenario={body:OperatingPlanBody;evaluation:OperatingEvaluation;guidance:OperatingGuidance;evidence:OperatingEvidence;handoff:Record<string,unknown>|null};
export function recognizableScenario(name:RecognizableCase):Scenario{const base=encoded.source_confirmed as Record<string,unknown>,extra=encoded[name] as Record<string,unknown>;return structuredClone(Object.fromEntries([...new Set([...Object.keys(base),...Object.keys(extra)])].map(key=>[key,extra[key]&&typeof extra[key]==="object"&&!Array.isArray(extra[key])?{...(base[key] as object),...(extra[key] as object)}:key in extra?extra[key]:base[key]]))) as unknown as Scenario;}
export function recognizableInitial(name:RecognizableCase="source_confirmed"){return recognizableScenario(name).body;}
export function recognizableSnapshot(body:OperatingPlanBody,revision:number,name:RecognizableCase="source_confirmed"):FinancialWorkspaceSnapshot{const base=operatingEditSnapshot(body,revision);return{...base,evidence:(recognizableScenario(name).evidence.files??[]).map(row=>({...row,content_type:"application/pdf"}))};}
/** Metadata references only: labels/lineage identify UI-created siblings; no finance is calculated here. */
export function recognizableReply(body:OperatingPlanBody,name:RecognizableCase="source_confirmed"){
 const scenario=recognizableScenario(name),ids=new Map<string,string>();
 for(const ref of scenario.body.expenses??[]){const row=body.expenses?.find(row=>row.id===ref.id&&Boolean(row.excluded)===Boolean(ref.excluded))||body.expenses?.find(row=>row.label===ref.label&&row.category===ref.category&&row.source_group_key===ref.source_group_key&&Boolean(row.excluded)===Boolean(ref.excluded));if(row)ids.set(ref.id,row.id);}
 for(const ref of scenario.body.adjustments??[]){const row=body.adjustments?.find(row=>row.id===ref.id)||body.adjustments?.find(row=>(row.expense_row_id??"")===(ids.get(ref.expense_row_id??"")??ref.expense_row_id??"")&&row.command?.target===ref.command?.target&&(!ref.source_group_key||row.source_group_key===ref.source_group_key))||body.adjustments?.find(row=>row.label===ref.label&&row.kind===ref.kind);if(row)ids.set(ref.id,row.id);}
 let json=JSON.stringify({evaluation:scenario.evaluation,guidance:scenario.guidance,evidence:scenario.evidence});for(const[oldId,newId]of ids)json=json.replaceAll(oldId,newId);return JSON.parse(json) as {evaluation:OperatingEvaluation;guidance:OperatingGuidance;evidence:OperatingEvidence};
}
